def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {value: sum(row.count(value) for row in grid) for value in {cell for row in grid for cell in row}}
    background = max(counts, key=counts.get)
    output = [row[:] for row in grid]

    for r in range(h):
        markers = [c for c in range(w) if grid[r][c] != background]
        if len(markers) >= 2:
            for c in range(min(markers) + 1, max(markers)):
                if grid[r][c] == background:
                    output[r][c] = 3

    for c in range(w):
        markers = [r for r in range(h) if grid[r][c] != background]
        if len(markers) >= 2:
            for r in range(min(markers) + 1, max(markers)):
                if grid[r][c] == background:
                    output[r][c] = 3

    return output
